def parse_duration(s: str) -> int:
    if not s:
        raise ValueError("Invalid duration format")

    unit_values = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    unit_indices = {'d': 0, 'h': 1, 'm': 2, 's': 3}

    total = 0
    i = 0
    last_unit_index = -1

    while i < len(s):
        # Parse number (one or more digits)
        if not s[i].isdigit():
            raise ValueError("Invalid duration format")

        num_start = i
        while i < len(s) and s[i].isdigit():
            i += 1

        number = int(s[num_start:i])

        # Parse unit (single letter)
        if i >= len(s):
            raise ValueError("Invalid duration format")

        unit = s[i]
        i += 1

        # Validate unit
        if unit not in unit_values:
            raise ValueError("Invalid duration format")

        # Check unit order (no repeats, no backwards)
        current_unit_index = unit_indices[unit]
        if current_unit_index <= last_unit_index:
            raise ValueError("Invalid duration format")

        last_unit_index = current_unit_index
        total += number * unit_values[unit]

    return total

def parse_duration(s: str) -> int:
    if not s:
        raise ValueError("Empty string")

    unit_values = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    unit_order = 'dhms'
    last_unit_index = -1

    total_seconds = 0
    current_number = ""

    for char in s:
        if char.isdigit():
            current_number += char
        elif char in unit_values:
            if not current_number:
                raise ValueError("Unit without a preceding number")

            current_unit_index = unit_order.index(char)
            if current_unit_index <= last_unit_index:
                raise ValueError("Unit out of order or repeated")

            value = int(current_number)
            total_seconds += value * unit_values[char]

            last_unit_index = current_unit_index
            current_number = ""
        else:
            raise ValueError(f"Invalid character: {char}")

    if current_number:
        raise ValueError("Number without a unit")

    return total_seconds

def int_to_english(n: int) -> str:
    """Convert an integer to English words."""
    if n < 0 or n > 999_999_999:
        raise ValueError("n must be in range 0 <= n <= 999_999_999")

    if n == 0:
        return "zero"

    ones = ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine"]
    teens = ["ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen",
             "sixteen", "seventeen", "eighteen", "nineteen"]
    tens = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]

    def convert_below_thousand(num):
        """Convert a number 0-999 to words."""
        if num == 0:
            return ""

        parts = []

        # Hundreds place
        if num >= 100:
            parts.append(ones[num // 100])
            parts.append("hundred")
            num %= 100

        # Tens and ones place
        if num >= 20:
            tens_digit = num // 10
            ones_digit = num % 10
            if ones_digit == 0:
                parts.append(tens[tens_digit])
            else:
                parts.append(tens[tens_digit] + "-" + ones[ones_digit])
        elif num >= 10:
            parts.append(teens[num - 10])
        elif num > 0:
            parts.append(ones[num])

        return " ".join(parts)

    # Split number into groups of three
    millions = n // 1_000_000
    thousands = (n % 1_000_000) // 1_000
    remainder = n % 1_000

    parts = []

    if millions > 0:
        parts.append(convert_below_thousand(millions))
        parts.append("million")

    if thousands > 0:
        parts.append(convert_below_thousand(thousands))
        parts.append("thousand")

    if remainder > 0:
        parts.append(convert_below_thousand(remainder))

    return " ".join(parts)

def int_to_english(n: int) -> str:
    # Validate input
    if isinstance(n, bool) or not isinstance(n, int) or n < 0 or n > 999_999_999:
        raise ValueError("n must be an integer in the range 0 <= n <= 999_999_999")

    # Special case for zero
    if n == 0:
        return "zero"

    # Define word mappings
    ones = ["", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
            "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen",
            "seventeen", "eighteen", "nineteen"]

    tens = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]

    scales = ["", "thousand", "million"]

    def convert_below_thousand(num):
        """Convert a number below 1000 to words"""
        if num == 0:
            return ""
        elif num < 20:
            return ones[num]
        elif num < 100:
            ten_digit = num // 10
            one_digit = num % 10
            if one_digit == 0:
                return tens[ten_digit]
            else:
                return tens[ten_digit] + "-" + ones[one_digit]
        else:
            hundred_digit = num // 100
            remainder = num % 100
            result = ones[hundred_digit] + " hundred"
            if remainder > 0:
                result += " " + convert_below_thousand(remainder)
            return result

    # Break the number into groups of three digits
    groups = []
    while n > 0:
        groups.append(n % 1000)
        n //= 1000

    # Convert each group and add scale words
    result_parts = []
    for i in range(len(groups) - 1, -1, -1):
        if groups[i] > 0:
            group_word = convert_below_thousand(groups[i])
            if i > 0:
                group_word += " " + scales[i]
            result_parts.append(group_word)

    return " ".join(result_parts)

def eval_rpn(tokens: list[str]) -> int:
    stack = []
    operators = {'+', '-', '*', '/'}

    for token in tokens:
        if token in operators:
            # Pop two operands (right operand first, then left operand)
            right = stack.pop()
            left = stack.pop()

            if token == '+':
                result = left + right
            elif token == '-':
                result = left - right
            elif token == '*':
                result = left * right
            else:  # token == '/'
                # Integer division toward zero (not toward negative infinity)
                # Python's // truncates toward negative infinity, so we adjust
                q = left // right
                # If there's a remainder and signs differ, adjust toward zero
                if (left % right != 0) and ((left < 0) != (right < 0)):
                    q += 1
                result = q

            stack.append(result)
        else:
            # It's a number token
            stack.append(int(token))

    return stack[0]

def eval_rpn(tokens: list[str]) -> int:
    stack = []
    operators = {'+', '-', '*', '/'}

    for token in tokens:
        if token in operators:
            # Pop right operand first, then left (stack order matters)
            right = stack.pop()
            left = stack.pop()

            if token == '+':
                result = left + right
            elif token == '-':
                result = left - right
            elif token == '*':
                result = left * right
            else:  # token == '/'
                # int(a/b) truncates toward zero (like C/Java)
                result = int(left / right)

            stack.append(result)
        else:
            # Parse as integer (handles negative numbers like "-11")
            stack.append(int(token))

    return stack[0]

def camel_to_snake(name: str) -> str:
    result = []

    for i, char in enumerate(name):
        if char.isupper():
            if i > 0:
                prev_char = name[i - 1]
                # Rule 1: insert before uppercase if preceded by lowercase or digit
                if prev_char.islower() or prev_char.isdigit():
                    result.append('_')
                # Rule 2: insert before uppercase if it's the last of an uppercase run
                # and is followed by lowercase
                elif prev_char.isupper() and i + 1 < len(name) and name[i + 1].islower():
                    result.append('_')

        result.append(char.lower())

    return ''.join(result)

def camel_to_snake(name: str) -> str:
    result = []

    for i, char in enumerate(name):
        if char.isupper():
            # Check if we need to insert underscore before this uppercase letter
            if i > 0:
                prev_char = name[i - 1]
                # Rule 1: lowercase or digit followed by uppercase
                if prev_char.islower() or prev_char.isdigit():
                    result.append('_')
                # Rule 2: inside a run of uppercase letters,
                # insert before last uppercase when followed by lowercase
                elif prev_char.isupper():
                    if i + 1 < len(name) and name[i + 1].islower():
                        result.append('_')

            result.append(char.lower())
        else:
            result.append(char)

    return ''.join(result)


