def camel_to_snake(name: str) -> str:
    result = []

    for i, char in enumerate(name):
        if char.isupper():
            if i > 0:
                prev = name[i-1]
                # Rule 1: lowercase or digit before uppercase
                # Rule 2: uppercase before uppercase followed by lowercase
                if (prev.islower() or prev.isdigit() or 
                    (prev.isupper() and i + 1 < len(name) and name[i+1].islower())):
                    result.append('_')

        result.append(char.lower())

    return ''.join(result)

def word_wrap(text: str, width: int) -> list[str]:
    words = text.split()
    if not words:
        return []

    lines = []
    current_line = ""

    for word in words:
        if len(word) <= width:
            # Word fits within width
            if current_line:
                test_line = current_line + " " + word
                if len(test_line) <= width:
                    # Add word to current line
                    current_line = test_line
                else:
                    # Word doesn't fit, start new line
                    lines.append(current_line)
                    current_line = word
            else:
                # Current line is empty, start with this word
                current_line = word
        else:
            # Word is longer than width, need to split it
            if current_line:
                # Finalize current line
                lines.append(current_line)
                current_line = ""

            # Split the word into chunks of exactly width characters
            i = 0
            while i + width < len(word):
                lines.append(word[i:i+width])
                i += width

            # Last piece (shorter or equal to width) starts the current line
            current_line = word[i:]

    # Don't forget the last line
    if current_line:
        lines.append(current_line)

    return lines

def word_wrap(text: str, width: int) -> list[str]:
    words = text.split()
    if not words:
        return []

    lines = []
    current_line = ""

    for word in words:
        if len(word) <= width:
            # Word fits within width
            if current_line:
                # Try to add to current line
                if len(current_line) + 1 + len(word) <= width:
                    current_line += " " + word
                else:
                    # Doesn't fit, save current line and start new one
                    lines.append(current_line)
                    current_line = word
            else:
                # Current line is empty, start with this word
                current_line = word
        else:
            # Word is longer than width, must split it
            if current_line:
                lines.append(current_line)

            # Split word into width-sized pieces
            for i in range(0, len(word), width):
                piece = word[i:i+width]
                if i + width < len(word):
                    # Not the last piece, add to output
                    lines.append(piece)
                else:
                    # Last piece, becomes new current line
                    current_line = piece

    # Add any remaining content
    if current_line:
        lines.append(current_line)

    return lines

def word_wrap(text: str, width: int) -> list[str]:
    words = text.split()
    if not words:
        return []

    result = []
    current_line = ""

    for word in words:
        if len(word) <= width:
            # Word fits within width
            if current_line:
                # Check if adding this word fits on current line
                if len(current_line) + 1 + len(word) <= width:
                    current_line += " " + word
                else:
                    # Word doesn't fit, save current line and start new one
                    result.append(current_line)
                    current_line = word
            else:
                # Current line is empty
                current_line = word
        else:
            # Word is longer than width, need to cut it
            if current_line:
                result.append(current_line)
                current_line = ""

            # Cut the word into pieces of width characters
            for i in range(0, len(word), width):
                piece = word[i:i+width]
                if i + width < len(word):
                    # Not the last piece - add to result
                    result.append(piece)
                else:
                    # Last piece - becomes start of current line
                    current_line = piece

    # Add any remaining content
    if current_line:
        result.append(current_line)

    return result
